B.b6a=new A.bo(9,"odjede","sfx_story_truck_leave",null,1)
B.b6x=new A.bo(9,"tik\xe1n\xed","sfx_story_soft_ticking",null,1)
B.a7K=s([B.b6u,B.b6g,B.b6a,B.b6x],t.c)
B.aHH=new A.h(0,0,170.20355132091814,311.82330012992634)
B.aIe=new A.h(120,0,311.85794716327416,170.20355132091814)
B.aFu=new A.h(129.9,129.9,311.79692507579034,311.79692507579034)
B.iY=s([B.aHH,B.aIe,B.aFu],t.u)
B.aha=new A.b1("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.c6=new A.lS("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.a2u=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.aUo=new A.a8(B.c6,B.a2u,!1)
B.be=new A.lS("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.a5R=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.aWk=new A.a8(B.be,B.a5R,!1)
B.aa3=s([B.aha,B.aUo,B.aWk],t.a)
B.aXk=new A.cy("story_00_intro",B.aa3)
B.agE=new A.b1("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.a3b=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.aUw=new A.a8(B.c6,B.a3b,!1)
B.ahh=new A.b1("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.a3k=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.aUs=new A.a8(B.be,B.a3k,!1)
B.cc=new A.lS("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.ab1=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.aW9=new A.a8(B.cc,B.ab1,!1)
B.a3x=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.aVB=new A.a8(B.c6,B.a3x,!1)
B.aad=s([B.agE,B.aUw,B.ahh,B.aUs,B.aW9,B.aVB],t.a)
B.aX2=new A.cy("story_01a_clubhouse_arrival",B.aad)
B.a4B=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.aV0=new A.a8(B.c6,B.a4B,!1)
B.a6b=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.aVF=new A.a8(B.cc,B.a6b,!1)
B.a1z=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.aVX=new A.a8(B.be,B.a1z,!1)
B.a3g=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.aVU=new A.a8(B.cc,B.a3g,!1)
B.a2w=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.aVd=new A.a8(B.be,B.a2w,!1)
B.a0x=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.aUb=new A.a8(B.c6,B.a0x,!1)
B.a8j=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.aWo=new A.a8(B.be,B.a8j,!1)
B.acc=s([B.aV0,B.aVF,B.aVX,B.aVU,B.aVd,B.aUb,B.aWo],t.a)
B.aWY=new A.cy("story_01b_legend_and_time",B.acc)
B.ahI=new A.b1("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.a4F=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.aV7=new A.a8(B.be,B.a4F,!1)
B.a44=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.aWx=new A.a8(B.cc,B.a44,!1)
B.abH=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.aVT=new A.a8(B.be,B.abH,!1)
B.a7W=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.aU6=new A.a8(B.cc,B.a7W,!1)
B.a2i=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.aU9=new A.a8(B.c6,B.a2i,!1)
B.a6G=s([B.ahI,B.aV7,B.aWx,B.aVT,B.aU6,B.aU9],t.a)
B.aWX=new A.cy("story_02_torn_map",B.a6G)
B.a1A=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.aV6=new A.a8(B.c6,B.a1A,!1)
B.a8K=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.aWe=new A.a8(B.be,B.a8K,!1)
B.agY=new A.b1("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.ab5=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.aWf=new A.a8(B.cc,B.ab5,!1)
B.abk=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.aWi=new A.a8(B.be,B.abk,!1)
B.a7t=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.aUu=new A.a8(B.c6,B.a7t,!1)
B.a1W=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.aUZ=new A.a8(B.be,B.a1W,!1)
B.a20=s([B.aV6,B.aWe,B.agY,B.aWf,B.aWi,B.aUu,B.aUZ],t.a)
B.aWZ=new A.cy("story_03_founders_trail",B.a20)
B.agG=new A.b1("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.a3J=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.aWs=new A.a8(B.be,B.a3J,!1)
B.a8e=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.aVO=new A.a8(B.cc,B.a8e,!1)
B.aaM=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.aVY=new A.a8(B.be,B.aaM,!1)
B.a4W=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.aVG=new A.a8(B.c6,B.a4W,!1)
B.a18=s([B.agG,B.aWs,B.aVO,B.aVY,B.aVG],t.a)
B.aWV=new A.cy("story_04_flowers_in_mud",B.a18)
B.ah2=new A.b1("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.a2V=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.aUD=new A.a8(B.be,B.a2V,!1)
B.a0C=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.aVA=new A.a8(B.cc,B.a0C,!1)
B.a5r=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.aWB=new A.a8(B.be,B.a5r,!1)
B.acl=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.aUY=new A.a8(B.c6,B.acl,!1)
B.a7Q=s([B.ah2,B.aUD,B.aVA,B.aWB,B.aUY],t.a)
B.aXu=new A.cy("story_05_old_oak",B.a7Q)
B.agZ=new A.b1("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.a8P=s(["\u201eCo se to stalo?\u201c"],t.s)
B.aWj=new A.a8(B.be,B.a8P,!1)
B.a5h=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.aUW=new A.a8(B.c6,B.a5h,!1)
B.a32=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.aUU=new A.a8(B.be,B.a32,!1)
B.a5T=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.aVJ=new A.a8(B.c6,B.a5T,!1)
B.agL=new A.b1("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.a5u=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.aVx=new A.a8(B.cc,B.a5u,!1)
B.ac2=s([B.agZ,B.aWj,B.aUW,B.aUU,B.aVJ,B.agL,B.aVx],t.a)
B.aX_=new A.cy("story_06_waterfall_chest",B.ac2)
B.ahg=new A.b1("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.a47=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.aWD=new A.a8(B.cc,B.a47,!1)
B.abZ=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.aUX=new A.a8(B.c6,B.abZ,!1)
B.ahz=new A.b1("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.aca=s([B.ahg,B.aWD,B.aUX,B.ahz],t.a)
B.aXf=new A.cy("story_07_scroll",B.aca)
B.agw=new A.b1("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aaB=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.aWt=new A.a8(B.be,B.aaB,!1)
B.a9k=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.aTZ=new A.a8(B.cc,B.a9k,!1)
B.a3d=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.aU3=new A.a8(B.be,B.a3d,!1)
B.a6s=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.aUE=new A.a8(B.cc,B.a6s,!1)
B.a7i=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.aWg=new A.a8(B.c6,B.a7i,!1)
B.a7R=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.aTW=new A.a8(B.cc,B.a7R,!1)
B.a7M=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.aUG=new A.a8(B.be,B.a7M,!1)
B.a5s=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.aVn=new A.a8(B.cc,B.a5s,!1)
B.a2t=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.aUr=new A.a8(B.c6,B.a2t,!1)
B.a2a=s([B.agw,B.aWt,B.aTZ,B.aU3,B.aUE,B.aWg,B.aTW,B.aUG,B.aVn,B.aUr],t.a)
B.aX5=new A.cy("story_08_ending_dialogue",B.a2a)
